from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];H=json.loads((R/'hyperbook-data.json').read_text());records={r['id']:r for r in H['records']};site='https://computerlars.github.io/Summa-Transscriptus/'
lines=['# Summa Transscriptus','**[Læs Summa Transscriptus · GitHub Pages]('+site+')**','**Organ for de Autonome Videnskaber. *Under Bugten — Disputter over Computer Lars-spektaklet*. Aarhus Bugt Center for Kunst på Det Jyske Kunstakademi, Mejlgade 32, Aarhus, 17.–24. september 2023.**','Optagelser, skriftlige forlæg, læseudgave og de oprindelige maskinsynteser fra disputterne om Computer Lars. Den sammenhængende læsning forbinder rammeteksten og proceduren med fremsættelser, modsigelser og synteser.','## Disputationes','| Dato | Disput | Læseudgaver |\n| --- | --- | --- |']
for g in H['groups']:lines.append('| '+g['date']+' | ['+g['guest']+' og Computer Lars]('+site+'#disput-'+str(g['number'])+') | [Tekst]('+g['path']+'/reading.md) · [Word]('+g['path']+'/reading.docx) |')
lines+=['## Ramme og procedure','> Var munkemarxisterne de sidste systemdigtere?','— [Praefatio]('+site+'#praefatio), [samledokumentet §4]('+site+'manuscript.html#p4).','Fire disputationer blev annonceret: 18. september kl. 16–20 samt 20., 22. og 24. september kl. 18–22. De første tre aftener omfatter hver fire tese–antitese-par, otte fremsættelser. Den sidste er en metadisput med Logistique. En kort pseudotese og supplerende optagelser er bevaret i arkivet. Programmets tider er ikke optagelsernes målte længder.','Scriptet afsætter tyve minutter pr. fremsættelse og fem minutter til indlæg ex auditorio. Et sådant indlæg skal holdes inden for to minutter og fremsætte en begrundet afvisning eller en distinktion. Praeses leder forløbet.','Navnene følger opførelsen: Mikhailos Boltus, Maia Bacchus, Petrus Borumanum, Logistique, Computer Lars og Praeses. Begge kunstnerstemmer optræder som Computer Lars. Ex auditorio betegner indlæg fra salen; en uidentificeret indskudt replik betegnes Interventio.','[Rammetekst]('+site+'#praefatio) · [Ordo disputandi]('+site+'#apparatus) · [Manuscriptum]('+site+'manuscript.html) · [Original Word-fil](sources/under-bugten/manuscript.docx) · [Ordret tekstudtræk](sources/under-bugten/manuscript.md) · [Proveniens](sources/under-bugten/source.json).','## Teser, antiteser og kilder']
for g in H['groups']:
 lines+=['### '+str(g['number'])+' · '+g['guest']]
 if g['number']<4:
  lines+=['| Tese | Antitese | Maskinsynteser fra 2023 |\n| --- | --- | --- |']
  for i in range(0,min(8,len(g['records'])),2):
   a,b=[records[x]for x in g['records'][i:i+2]]
   hist=lambda r:'[Syntese · '+r['id']+']('+H['collation']['records'][r['id']]['historical']['url']+')'
   lines.append('| ['+a['title']+']('+site+'#disput/'+a['id']+') | ['+b['title']+']('+site+'#disput/'+b['id']+') | '+hist(a)+' · '+hist(b)+' |')
  if g['number']==3:lines.append('[Pseudotese · D3-09]('+site+'#disput/D3-09).')
 else:
  for rid in g['records']:
   r=records[rid];hist=H['collation']['records'][rid].get('historical');lines.append('- ['+r['title']+']('+site+'#disput/'+rid+')'+(' · [Maskinsyntese]('+hist['url']+')' if hist else ''))
lines+=['## Tekst og kilder','**Optagelserne, 2023.** De oprindelige M4A-filer er registreret i [optagelsesoversigten](documentation/recordings.md). MP3-lyttekopierne følger samme forløb uden beskæring. Tiderne regnes fra begyndelsen af den enkelte optagelse. [Lyttekopier](https://github.com/ComputerLars/Summa-Transscriptus/releases/tag/audio-access-20261017).','**Transskriptioner og synteser, 2023.** [56 TXT-filer](archive/2023/) er bevaret uændret. De 48 tilknyttede maskinsynteser afslutter de respektive forløb på læsesiden i deres oprindelige ordlyd. Syntesernes fejl, navne og slutninger tilhører dette historiske tekstlag.','**Manuskriptet.** Samledokumentet rummer rammetekst, procedure, planer, teser, antiteser, tabeller, billeder og historiske tekster. Dets 492 ikke-tomme tekstafsnit og syv indlejrede billeder er bevaret i den diplomatiske udgave. Dets afsnitsnumre er kildeadresser.','**Læseudgaven, oktober 2026.** Renskrivning på grundlag af optagelser, tidligere genkendelser og skriftlige forlæg. En fortsat taler har én betegnelse med flere afsnit. Optagelses- og genkendelsesenhederne bevares som lydsteder og tekstankre. Lokal tegnsætning, navneformer og rettelser er registreret i [rettelseslisten](documentation/reading-corrections.json); kildebaserede talerafstemninger i [positionsregisteret](documentation/position-readings.json).','## Imagines','[Udstillingsfotografier](sources/under-bugten/photos/) og [billedproveniens](sources/under-bugten/photos/sources.json). Billederne vises i hele deres bevarede udsnit; fotografangivelse følger den tilgængelige dokumentation.','## Collectanea','[Collectanea]('+site+'#bog) samler valgte tekstforløb, lydsteder, synteser og billeder med egne anmærkninger. Udvalget gemmes i browseren. [Den samlede PDF](Summa-Transscriptus.pdf) følger den aktuelle læseudgave. **Hent PDF** danner en A5-bog med marginer, indhold, sidetal og kilderegister. **Samlet udgave · PDF** danner den sammenhængende udgave med rammetekst og alle hovedforløb. PDF-dannelsen foregår lokalt i browseren.','## Arkiv og rettigheder','[Filmanifest](FILE-MANIFEST.json) · [Redaktionelle principper](documentation/editorial-principles.md) · [Kilder](documentation/references.md) · [Licens](LICENSE).','Computer Lars-projektets senere ph.d.-afhandling: [Asker Bryld Staunæs, *Syntheticism: How I Learned to Love Democracy*](https://github.com/ComputerLars/Syntheticism-How-I-Learned-to-Love-Democracy).']
(R/'README.md').write_text('\n\n'.join(lines)+'\n')
